DO $dairy$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "requeson-casero-de-leche", "public_path": "/requeson-casero-de-leche", "title": "Requesón casero de leche, suave y sin prensar", "excerpt": "Prepara requesón casero de leche y limón, con textura suave para rellenos o desayunos. Fotos de cuajado y escurrido, rendimiento y conservación en nevera.", "summary": "Esta versión de requesón se prepara con leche entera y limón y queda suelta y húmeda, parecida a una ricotta de leche. No es la ricotta tradicional hecha solo de suero. Con 2 litros salen unos 300–450 g; calculamos 350 g.", "content_html": "<p>Esta versión de requesón se prepara con leche entera y limón y queda suelta y húmeda, parecida a una ricotta de leche. No es la ricotta tradicional hecha solo de suero. Con 2 litros salen unos 300–450 g; calculamos 350 g.</p>", "notes": "<h3>Consejos y conservación</h3><p>Consume en 2–3 días. El tiempo total usa 30 minutos de escurrido. El limón extra solo se añade si hace falta; no se incluye en la estimación nutricional. El suero obtenido es ácido y no sustituye leche o crema para yogur o mantequilla. Sin prueba de cocina propia. Contiene leche. Usa utensilios limpios y desinfectados y conserva a 4 °C o menos. No es una conserva para guardar a temperatura ambiente.</p><ul><li><a href=\"https://ucanr.edu/sites/camasterfoodpreservers/files/404614.pdf\">UC Master Food Preservers — whole milk ricotta, page 21</a></li><li><a href=\"https://cheesemaking.com/pages/ricotta-cheese-making-recipe-instructions\">New England Cheesemaking — ricotta</a></li></ul>", "ingredients": [{"name": "leche entera pasteurizada, preferiblemente no UHT", "amount": "2000", "unit": "ml"}, {"name": "zumo de limón recién exprimido y colado", "amount": "60", "unit": "ml"}, {"name": "sal fina", "amount": "2", "unit": "g"}], "steps": [{"title": "Calienta la leche", "content": "Limpia y desinfecta olla, colador y tela. Calienta la leche removiendo suavemente hasta 88–90 °C, sin hervor fuerte. Retira del fuego.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-01.webp", "image_alt": "Calienta la leche — Requesón casero de leche, suave y sin prensar"}, {"title": "Forma los copos", "content": "Añade el limón y la sal y mezcla solo 2–3 vueltas. Deja quieto 10 minutos: deben separarse copos blancos y suero amarillento. Si sigue lechoso, añade hasta 15 ml más de limón y espera 5 minutos; la acidez natural varía.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-02.webp", "image_alt": "Forma los copos — Requesón casero de leche, suave y sin prensar"}, {"title": "Escurre sin prensar", "content": "Recoge los copos con espumadera en una tela fina sobre colador y bol. Escurre 10–15 minutos para textura húmeda. No exprimas; para mayor firmeza, continúa hasta 30 minutos dentro de la nevera.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-03.webp", "image_alt": "Escurre sin prensar — Requesón casero de leche, suave y sin prensar"}, {"title": "Enfría y guarda", "content": "Pasa a un recipiente limpio, tapa y refrigera al menos 2 horas. Sirve desmigado o en rellenos. No lo tritures si quieres conservar la textura de copos.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-04.webp", "image_alt": "Enfría y guarda — Requesón casero de leche, suave y sin prensar"}], "category": "Guarniciones", "course": "Guarniciones", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 190, "servings": 7, "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "alt": "Requesón casero de leche, suave y sin prensar"}], "video_urls": [], "keywords": ["Requesón casero de leche, suave y sin prensar"], "nutrition": {"calories": 87, "protein_g": 5.6, "carbs_g": 1.5, "fat_g": 6.5, "serving_size": "1 de 7 porciones, unos 50 g", "estimated": true, "note": "Estimación por porción; el rendimiento, la humedad y la marca cambian los valores.", "source": "USDA FoodData Central generic whole-milk ricotta proxy", "method": "Finished ricotta reference per 100 g:174 kcal,11.2 g protein,3 g carbohydrate,13 g fat; multiply by 0.5 per 50 g portion. Assumed yield350 g from2 L milk; actual300–450 g. Whey excluded; not a sum of all milk nutrients."}, "seo": {"title": "Requesón casero de leche, suave y sin prensar", "description": "Prepara requesón casero de leche y limón, con textura suave para rellenos o desayunos. Fotos de cuajado y escurrido, rendimiento y conservación en nevera.", "author": "Néstor Bastidas", "image_alt": "Requesón casero de leche, suave y sin prensar", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "¿Puedo usar solo suero?", "a": "No con estas cantidades: el suero tiene otras proteínas y otra acidez. Esta receta está formulada para leche."}, {"q": "¿Por qué queda seco?", "a": "Mucho escurrido, presión o hervor fuerte secan los copos. Escurre menos y sin peso."}], "additional_time_minutes": 160}, "published": false, "editorial_status": "ready"}, {"language": "en", "slug": "homemade-whole-milk-ricotta", "public_path": "/en/homemade-whole-milk-ricotta", "title": "Homemade whole-milk ricotta, soft and unpressed", "excerpt": "Make soft whole-milk ricotta with lemon juice for fillings and breakfasts. Photos explain curd formation, gentle draining, approximate yield and cold storage.", "summary": "This requeson-style cheese uses whole milk and lemon and stays loose and moist, like whole-milk ricotta. It is not traditional whey-only ricotta. Two litres yield about 300–450 g; the estimate here is 350 g.", "content_html": "<p>This requeson-style cheese uses whole milk and lemon and stays loose and moist, like whole-milk ricotta. It is not traditional whey-only ricotta. Two litres yield about 300–450 g; the estimate here is 350 g.</p>", "notes": "<h3>Tips and storage</h3><p>Use within 2–3 days. Total time assumes 30 minutes draining. Extra lemon is only added if needed and is excluded from nutrition estimates. Acid whey cannot replace milk or cream for yogurt or butter. Not kitchen-tested. Contains milk. Use clean, sanitized equipment and refrigerate at 4 °C or below. This is not a shelf-stable canned product.</p><ul><li><a href=\"https://ucanr.edu/sites/camasterfoodpreservers/files/404614.pdf\">UC Master Food Preservers — whole milk ricotta, page 21</a></li><li><a href=\"https://cheesemaking.com/pages/ricotta-cheese-making-recipe-instructions\">New England Cheesemaking — ricotta</a></li></ul>", "ingredients": [{"name": "pasteurized whole milk, preferably not UHT", "amount": "2000", "unit": "ml"}, {"name": "freshly squeezed strained lemon juice", "amount": "60", "unit": "ml"}, {"name": "fine salt", "amount": "2", "unit": "g"}], "steps": [{"title": "Heat the milk", "content": "Sanitize pot, strainer and cloth. Heat milk gently while stirring to 88–90 °C, without a vigorous boil. Remove from heat.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-01.webp", "image_alt": "Heat the milk — Homemade whole-milk ricotta, soft and unpressed"}, {"title": "Form the curds", "content": "Add lemon juice and salt and stir only 2–3 turns. Leave undisturbed for 10 minutes until white flakes separate from yellowish whey. If still milky, add up to 15 ml extra lemon and wait 5 minutes; lemon acidity varies.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-02.webp", "image_alt": "Form the curds — Homemade whole-milk ricotta, soft and unpressed"}, {"title": "Drain without pressing", "content": "Ladle curds into fine cloth in a strainer over a bowl. Drain 10–15 minutes for moist texture. Do not squeeze; for firmer cheese, continue up to 30 minutes in the refrigerator.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-03.webp", "image_alt": "Drain without pressing — Homemade whole-milk ricotta, soft and unpressed"}, {"title": "Chill and store", "content": "Transfer to a clean covered container and refrigerate at least 2 hours. Serve crumbled or in fillings. Avoid blending if you want to retain the delicate curds.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-04.webp", "image_alt": "Chill and store — Homemade whole-milk ricotta, soft and unpressed"}], "category": "Side dishes", "course": "Side dishes", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 190, "servings": 7, "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "alt": "Homemade whole-milk ricotta, soft and unpressed"}], "video_urls": [], "keywords": ["Homemade whole-milk ricotta, soft and unpressed"], "nutrition": {"calories": 87, "protein_g": 5.6, "carbs_g": 1.5, "fat_g": 6.5, "serving_size": "1 of 7 servings, about 50 g", "estimated": true, "note": "Estimated per serving; yield, moisture and brands affect the values.", "source": "USDA FoodData Central generic whole-milk ricotta proxy", "method": "Finished ricotta reference per 100 g:174 kcal,11.2 g protein,3 g carbohydrate,13 g fat; multiply by 0.5 per 50 g portion. Assumed yield350 g from2 L milk; actual300–450 g. Whey excluded; not a sum of all milk nutrients."}, "seo": {"title": "Homemade whole-milk ricotta, soft and unpressed", "description": "Make soft whole-milk ricotta with lemon juice for fillings and breakfasts. Photos explain curd formation, gentle draining, approximate yield and cold storage.", "author": "Néstor Bastidas", "image_alt": "Homemade whole-milk ricotta, soft and unpressed", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Can I use whey alone?", "a": "Not in these quantities: whey has different proteins and acidity. This recipe is formulated for milk."}, {"q": "Why is it dry?", "a": "Excess draining, pressing or vigorous boiling dries the curds. Drain less, without weights."}], "additional_time_minutes": 160}, "published": false, "editorial_status": "ready"}, {"language": "de", "slug": "ricotta-aus-vollmilch-selber-machen", "public_path": "/de/ricotta-aus-vollmilch-selber-machen", "title": "Weicher Ricotta aus Vollmilch ohne Pressen", "excerpt": "Weichen Ricotta aus Vollmilch und Zitronensaft herstellen. Fotos erklären Flockenbildung, sanftes Abtropfen, ungefähre Ausbeute und gekühlte Aufbewahrung.", "summary": "Dieser Requesón aus Vollmilch und Zitrone bleibt locker und feucht, ähnlich Vollmilch-Ricotta. Er ist kein traditioneller Ricotta nur aus Molke. Zwei Liter ergeben etwa 300–450 g; gerechnet wird mit 350 g.", "content_html": "<p>Dieser Requesón aus Vollmilch und Zitrone bleibt locker und feucht, ähnlich Vollmilch-Ricotta. Er ist kein traditioneller Ricotta nur aus Molke. Zwei Liter ergeben etwa 300–450 g; gerechnet wird mit 350 g.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>In 2–3 Tagen verbrauchen. Die Gesamtzeit umfasst 30 Minuten Abtropfen. Zusätzlicher Saft nur bei Bedarf; nicht in den Nährwerten enthalten. Saure Molke ersetzt keine Milch oder Sahne für Joghurt oder Butter. Nicht küchenerprobt. Enthält Milch. Saubere, desinfizierte Geräte verwenden und bei höchstens 4 °C lagern. Dies ist keine ungekühlt haltbare Konserve.</p><ul><li><a href=\"https://ucanr.edu/sites/camasterfoodpreservers/files/404614.pdf\">UC Master Food Preservers — whole milk ricotta, page 21</a></li><li><a href=\"https://cheesemaking.com/pages/ricotta-cheese-making-recipe-instructions\">New England Cheesemaking — ricotta</a></li></ul>", "ingredients": [{"name": "pasteurisierte Vollmilch, möglichst keine H-Milch", "amount": "2000", "unit": "ml"}, {"name": "frisch gepresster abgesiebter Zitronensaft", "amount": "60", "unit": "ml"}, {"name": "feines Salz", "amount": "2", "unit": "g"}], "steps": [{"title": "Milch erhitzen", "content": "Topf, Sieb und Tuch desinfizieren. Milch unter sanftem Rühren auf 88–90 °C erhitzen, nicht stark kochen. Vom Herd nehmen.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-01.webp", "image_alt": "Milch erhitzen — Weicher Ricotta aus Vollmilch ohne Pressen"}, {"title": "Flocken bilden", "content": "Zitronensaft und Salz zugeben, nur 2–3-mal umrühren. 10 Minuten ungestört stehen lassen, bis weiße Flocken und gelbliche Molke entstehen. Ist die Flüssigkeit milchig, bis zu 15 ml zusätzlichen Saft zugeben und 5 Minuten warten; Säure schwankt.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-02.webp", "image_alt": "Flocken bilden — Weicher Ricotta aus Vollmilch ohne Pressen"}, {"title": "Ohne Pressen abtropfen", "content": "Flocken mit Schaumlöffel in ein feines Tuch im Sieb über einer Schüssel geben. Für feuchte Konsistenz 10–15 Minuten abtropfen lassen. Nicht ausdrücken; für festeren Käse bis zu 30 Minuten im Kühlschrank abtropfen.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-03.webp", "image_alt": "Ohne Pressen abtropfen — Weicher Ricotta aus Vollmilch ohne Pressen"}, {"title": "Kühlen und lagern", "content": "In einen sauberen geschlossenen Behälter geben und mindestens 2 Stunden kühlen. Locker zerkrümelt oder in Füllungen verwenden. Nicht pürieren, wenn die Flocken erhalten bleiben sollen.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-04.webp", "image_alt": "Kühlen und lagern — Weicher Ricotta aus Vollmilch ohne Pressen"}], "category": "Beilagen", "course": "Beilagen", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 190, "servings": 7, "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "alt": "Weicher Ricotta aus Vollmilch ohne Pressen"}], "video_urls": [], "keywords": ["Weicher Ricotta aus Vollmilch ohne Pressen"], "nutrition": {"calories": 87, "protein_g": 5.6, "carbs_g": 1.5, "fat_g": 6.5, "serving_size": "1 von 7 Portionen, etwa 50 g", "estimated": true, "note": "Schätzung pro Portion; Ausbeute, Feuchtigkeit und Produkte beeinflussen die Werte.", "source": "USDA FoodData Central generic whole-milk ricotta proxy", "method": "Finished ricotta reference per 100 g:174 kcal,11.2 g protein,3 g carbohydrate,13 g fat; multiply by 0.5 per 50 g portion. Assumed yield350 g from2 L milk; actual300–450 g. Whey excluded; not a sum of all milk nutrients."}, "seo": {"title": "Weicher Ricotta aus Vollmilch ohne Pressen", "description": "Weichen Ricotta aus Vollmilch und Zitronensaft herstellen. Fotos erklären Flockenbildung, sanftes Abtropfen, ungefähre Ausbeute und gekühlte Aufbewahrung.", "author": "Néstor Bastidas", "image_alt": "Weicher Ricotta aus Vollmilch ohne Pressen", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Geht es nur mit Molke?", "a": "Nicht mit diesen Mengen: Molke hat andere Proteine und Säure. Dieses Rezept ist für Milch berechnet."}, {"q": "Warum wird er trocken?", "a": "Zu langes Abtropfen, Pressen oder starkes Kochen trocknet die Flocken. Kürzer und ohne Gewicht abtropfen."}], "additional_time_minutes": 160}, "published": false, "editorial_status": "ready"}, {"language": "fr", "slug": "ricotta-maison-au-lait-entier", "public_path": "/fr/ricotta-maison-au-lait-entier", "title": "Ricotta maison au lait entier, sans pressage", "excerpt": "Préparez une ricotta tendre au lait et au citron pour garnitures et petits-déjeuners. Photos du caillage, égouttage doux, rendement et conservation au frais.", "summary": "Ce requesón au lait entier et au citron reste souple et humide, proche d'une ricotta de lait. Ce n'est pas une ricotta traditionnelle de petit-lait seul. Deux litres donnent environ 300–450 g ; nous comptons 350 g.", "content_html": "<p>Ce requesón au lait entier et au citron reste souple et humide, proche d&#x27;une ricotta de lait. Ce n&#x27;est pas une ricotta traditionnelle de petit-lait seul. Deux litres donnent environ 300–450 g ; nous comptons 350 g.</p>", "notes": "<h3>Conseils et conservation</h3><p>Consommez sous 2–3 jours. Le total compte 30 minutes d&#x27;égouttage. Le citron supplémentaire, seulement si nécessaire, est exclu de l&#x27;estimation nutritionnelle. Le petit-lait acide ne remplace pas lait ou crème pour yaourt ou beurre. Non testée en cuisine. Contient du lait. Utilisez du matériel propre et désinfecté et conservez à 4 °C maximum. Cette préparation ne se conserve pas à température ambiante.</p><ul><li><a href=\"https://ucanr.edu/sites/camasterfoodpreservers/files/404614.pdf\">UC Master Food Preservers — whole milk ricotta, page 21</a></li><li><a href=\"https://cheesemaking.com/pages/ricotta-cheese-making-recipe-instructions\">New England Cheesemaking — ricotta</a></li></ul>", "ingredients": [{"name": "lait entier pasteurisé, de préférence non UHT", "amount": "2000", "unit": "ml"}, {"name": "jus de citron fraîchement pressé et filtré", "amount": "60", "unit": "ml"}, {"name": "sel fin", "amount": "2", "unit": "g"}], "steps": [{"title": "Chauffez le lait", "content": "Désinfectez casserole, passoire et tissu. Chauffez le lait en remuant doucement jusqu'à 88–90 °C sans forte ébullition. Retirez du feu.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-01.webp", "image_alt": "Chauffez le lait — Ricotta maison au lait entier, sans pressage"}, {"title": "Formez les flocons", "content": "Ajoutez citron et sel et remuez seulement 2–3 tours. Reposez 10 minutes sans bouger, jusqu'à séparation des flocons et du petit-lait jaunâtre. S'il reste laiteux, ajoutez jusqu'à 15 ml de citron et attendez 5 minutes ; l'acidité varie.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-02.webp", "image_alt": "Formez les flocons — Ricotta maison au lait entier, sans pressage"}, {"title": "Égouttez sans presser", "content": "Recueillez à l'écumoire dans un tissu fin sur une passoire et un bol. Égouttez 10–15 minutes pour garder de l'humidité. Ne serrez pas ; pour plus ferme, poursuivez jusqu'à 30 minutes au réfrigérateur.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-03.webp", "image_alt": "Égouttez sans presser — Ricotta maison au lait entier, sans pressage"}, {"title": "Refroidissez et gardez", "content": "Transférez dans une boîte propre fermée et réfrigérez au moins 2 heures. Servez émietté ou dans des farces. Ne mixez pas si vous souhaitez garder les flocons.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-04.webp", "image_alt": "Refroidissez et gardez — Ricotta maison au lait entier, sans pressage"}], "category": "Accompagnements", "course": "Accompagnements", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 190, "servings": 7, "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "alt": "Ricotta maison au lait entier, sans pressage"}], "video_urls": [], "keywords": ["Ricotta maison au lait entier, sans pressage"], "nutrition": {"calories": 87, "protein_g": 5.6, "carbs_g": 1.5, "fat_g": 6.5, "serving_size": "1 des 7 portions, environ 50 g", "estimated": true, "note": "Estimation par portion ; rendement, humidité et marques modifient les valeurs.", "source": "USDA FoodData Central generic whole-milk ricotta proxy", "method": "Finished ricotta reference per 100 g:174 kcal,11.2 g protein,3 g carbohydrate,13 g fat; multiply by 0.5 per 50 g portion. Assumed yield350 g from2 L milk; actual300–450 g. Whey excluded; not a sum of all milk nutrients."}, "seo": {"title": "Ricotta maison au lait entier, sans pressage", "description": "Préparez une ricotta tendre au lait et au citron pour garnitures et petits-déjeuners. Photos du caillage, égouttage doux, rendement et conservation au frais.", "author": "Néstor Bastidas", "image_alt": "Ricotta maison au lait entier, sans pressage", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Puis-je utiliser seulement du petit-lait ?", "a": "Pas avec ces proportions : protéines et acidité diffèrent. Cette recette est prévue pour du lait."}, {"q": "Pourquoi est-elle sèche ?", "a": "Égouttage long, pressage et forte ébullition dessèchent les flocons. Égouttez moins et sans poids."}], "additional_time_minutes": 160}, "published": false, "editorial_status": "ready"}, {"language": "it", "slug": "ricotta-casalinga-di-latte-intero", "public_path": "/it/ricotta-casalinga-di-latte-intero", "title": "Ricotta casalinga di latte intero, senza pressatura", "excerpt": "Prepara ricotta morbida di latte e limone per ripieni o colazioni. Foto di coagulazione e scolatura delicata, resa indicativa e conservazione in frigorifero.", "summary": "Questo requesón di latte intero e limone rimane morbido e umido, simile a una ricotta di latte. Non è la ricotta tradizionale di solo siero. Due litri rendono circa 300–450 g; qui calcoliamo 350 g.", "content_html": "<p>Questo requesón di latte intero e limone rimane morbido e umido, simile a una ricotta di latte. Non è la ricotta tradizionale di solo siero. Due litri rendono circa 300–450 g; qui calcoliamo 350 g.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Consuma entro 2–3 giorni. Il totale comprende 30 minuti di scolatura. Il limone extra si usa solo se necessario ed è escluso dalla nutrizione stimata. Il siero acido non sostituisce latte o panna per yogurt o burro. Non testata in cucina. Contiene latte. Usa utensili puliti e igienizzati e conserva a 4 °C o meno. Non è una conserva da tenere a temperatura ambiente.</p><ul><li><a href=\"https://ucanr.edu/sites/camasterfoodpreservers/files/404614.pdf\">UC Master Food Preservers — whole milk ricotta, page 21</a></li><li><a href=\"https://cheesemaking.com/pages/ricotta-cheese-making-recipe-instructions\">New England Cheesemaking — ricotta</a></li></ul>", "ingredients": [{"name": "latte intero pastorizzato, preferibilmente non UHT", "amount": "2000", "unit": "ml"}, {"name": "succo di limone appena spremuto e filtrato", "amount": "60", "unit": "ml"}, {"name": "sale fino", "amount": "2", "unit": "g"}], "steps": [{"title": "Scalda il latte", "content": "Igienizza pentola, colino e telo. Scalda mescolando piano fino a 88–90 °C, senza bollore forte. Togli dal fuoco.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-01.webp", "image_alt": "Scalda il latte — Ricotta casalinga di latte intero, senza pressatura"}, {"title": "Forma i fiocchi", "content": "Aggiungi limone e sale e mescola solo 2–3 giri. Lascia fermo 10 minuti finché si separano fiocchi bianchi e siero giallastro. Se resta lattiginoso, aggiungi fino a 15 ml di limone e aspetta 5 minuti; l'acidità varia.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-02.webp", "image_alt": "Forma i fiocchi — Ricotta casalinga di latte intero, senza pressatura"}, {"title": "Scola senza premere", "content": "Raccogli i fiocchi con schiumarola nel telo sopra colino e ciotola. Scola 10–15 minuti per una consistenza umida. Non strizzare; per rassodare, prosegui fino a 30 minuti in frigorifero.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-03.webp", "image_alt": "Scola senza premere — Ricotta casalinga di latte intero, senza pressatura"}, {"title": "Raffredda e conserva", "content": "Passa in un contenitore pulito e chiuso e refrigera almeno 2 ore. Usa sbriciolata o nei ripieni. Non frullare se vuoi mantenere i fiocchi.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-04.webp", "image_alt": "Raffredda e conserva — Ricotta casalinga di latte intero, senza pressatura"}], "category": "Contorni", "course": "Contorni", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 190, "servings": 7, "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "alt": "Ricotta casalinga di latte intero, senza pressatura"}], "video_urls": [], "keywords": ["Ricotta casalinga di latte intero, senza pressatura"], "nutrition": {"calories": 87, "protein_g": 5.6, "carbs_g": 1.5, "fat_g": 6.5, "serving_size": "1 di 7 porzioni, circa 50 g", "estimated": true, "note": "Stima per porzione; resa, umidità e prodotti possono cambiare i valori.", "source": "USDA FoodData Central generic whole-milk ricotta proxy", "method": "Finished ricotta reference per 100 g:174 kcal,11.2 g protein,3 g carbohydrate,13 g fat; multiply by 0.5 per 50 g portion. Assumed yield350 g from2 L milk; actual300–450 g. Whey excluded; not a sum of all milk nutrients."}, "seo": {"title": "Ricotta casalinga di latte intero, senza pressatura", "description": "Prepara ricotta morbida di latte e limone per ripieni o colazioni. Foto di coagulazione e scolatura delicata, resa indicativa e conservazione in frigorifero.", "author": "Néstor Bastidas", "image_alt": "Ricotta casalinga di latte intero, senza pressatura", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Posso usare solo siero?", "a": "Non con queste dosi: proteine e acidità sono diverse. La ricetta è formulata per latte."}, {"q": "Perché è secca?", "a": "Scolatura lunga, pressione o bollore forte asciugano i fiocchi. Scola meno e senza pesi."}], "additional_time_minutes": 160}, "published": false, "editorial_status": "ready"}, {"language": "ja", "slug": "homemade-whole-milk-ricotta", "public_path": "/ja/homemade-whole-milk-ricotta", "title": "牛乳とレモンで作る柔らかな自家製リコッタ", "excerpt": "全乳とレモンで作る、しっとり柔らかなリコッタ風チーズ。凝固と優しい水切りを写真で解説し、出来上がり量と冷蔵保存も紹介。朝食や詰め物に使えます。", "summary": "牛乳とレモンで作るレケソンで、全乳リコッタのように柔らかく粒が残ります。乳清だけを使う伝統製法とは異なります。牛乳2 Lで約300〜450 g、ここでは350 gを想定します。", "content_html": "<p>牛乳とレモンで作るレケソンで、全乳リコッタのように柔らかく粒が残ります。乳清だけを使う伝統製法とは異なります。牛乳2 Lで約300〜450 g、ここでは350 gを想定します。</p>", "notes": "<h3>コツと保存</h3><p>2〜3日以内に食べます。合計時間は水切り30分で計算しています。追加のレモン汁は必要時のみで、栄養推定に含めません。酸性の乳清はヨーグルトやバター用の牛乳・クリームの代わりになりません。調理試験は行っていません。 乳を含みます。清潔に洗浄・消毒した器具を使い、4 ℃以下で冷蔵してください。常温保存用の瓶詰めではありません。</p><ul><li><a href=\"https://ucanr.edu/sites/camasterfoodpreservers/files/404614.pdf\">UC Master Food Preservers — whole milk ricotta, page 21</a></li><li><a href=\"https://cheesemaking.com/pages/ricotta-cheese-making-recipe-instructions\">New England Cheesemaking — ricotta</a></li></ul>", "ingredients": [{"name": "殺菌済み全乳、できれば超高温殺菌ではないもの", "amount": "2000", "unit": "ml"}, {"name": "搾りたてのレモン汁、こしたもの", "amount": "60", "unit": "ml"}, {"name": "細かい塩", "amount": "2", "unit": "g"}], "steps": [{"title": "牛乳を温める", "content": "鍋、ざる、布を洗浄・消毒します。静かに混ぜながら88〜90 ℃に温め、激しく沸騰させず火を止めます。", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-01.webp", "image_alt": "牛乳を温める — 牛乳とレモンで作る柔らかな自家製リコッタ"}, {"title": "粒を作る", "content": "レモン汁と塩を加え、2〜3回だけ混ぜます。10分動かさず、白い粒と黄色みのある乳清に分かれるのを待ちます。まだ白濁していればレモン汁を最大15 ml追加し、5分待ちます。酸度によって変わります。", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-02.webp", "image_alt": "粒を作る — 牛乳とレモンで作る柔らかな自家製リコッタ"}, {"title": "押さずに水切りする", "content": "ボウルにざると細かい布を重ね、穴あきお玉で粒を移します。しっとり仕上げるなら10〜15分水切りします。絞りません。固めたい場合は冷蔵庫で合計30分まで続けます。", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-03.webp", "image_alt": "押さずに水切りする — 牛乳とレモンで作る柔らかな自家製リコッタ"}, {"title": "冷まして保存する", "content": "清潔なふた付き容器へ移し、最低2時間冷蔵します。粒をほぐして食べたり、詰め物に使ったりします。粒を残す場合はミキサーにかけません。", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-04.webp", "image_alt": "冷まして保存する — 牛乳とレモンで作る柔らかな自家製リコッタ"}], "category": "付け合わせ", "course": "付け合わせ", "cuisine": "各国料理", "difficulty": "簡単", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 190, "servings": 7, "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "alt": "牛乳とレモンで作る柔らかな自家製リコッタ"}], "video_urls": [], "keywords": ["牛乳とレモンで作る柔らかな自家製リコッタ"], "nutrition": {"calories": 87, "protein_g": 5.6, "carbs_g": 1.5, "fat_g": 6.5, "serving_size": "7食分の1、約50 g", "estimated": true, "note": "1食分の推定値です。出来上がり量、水分、製品により異なります。", "source": "USDA FoodData Central generic whole-milk ricotta proxy", "method": "Finished ricotta reference per 100 g:174 kcal,11.2 g protein,3 g carbohydrate,13 g fat; multiply by 0.5 per 50 g portion. Assumed yield350 g from2 L milk; actual300–450 g. Whey excluded; not a sum of all milk nutrients."}, "seo": {"title": "牛乳とレモンで作る柔らかな自家製リコッタ", "description": "全乳とレモンで作る、しっとり柔らかなリコッタ風チーズ。凝固と優しい水切りを写真で解説し、出来上がり量と冷蔵保存も紹介。朝食や詰め物に使えます。", "author": "Néstor Bastidas", "image_alt": "牛乳とレモンで作る柔らかな自家製リコッタ", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "乳清だけで作れますか。", "a": "この分量では作れません。たんぱく質や酸度が違います。このレシピは牛乳用です。"}, {"q": "ぱさつくのはなぜですか。", "a": "水切りしすぎ、圧搾、強い沸騰が原因になります。重石を使わず短く水切りします。"}], "additional_time_minutes": 160}, "published": false, "editorial_status": "ready"}, {"language": "pt", "slug": "ricota-caseira-de-leite", "public_path": "/pt/ricota-caseira-de-leite", "title": "Ricota caseira de leite, macia e sem prensar", "excerpt": "Faça ricota caseira de leite e limão, macia para recheios ou café da manhã. Fotos da coagulação e drenagem, rendimento aproximado e conservação na geladeira.", "summary": "Este requesón de leite integral e limão fica solto e úmido, semelhante à ricota de leite. Não é a ricota tradicional feita só de soro. Dois litros rendem cerca de 300–450 g; calculamos 350 g.", "content_html": "<p>Este requesón de leite integral e limão fica solto e úmido, semelhante à ricota de leite. Não é a ricota tradicional feita só de soro. Dois litros rendem cerca de 300–450 g; calculamos 350 g.</p>", "notes": "<h3>Dicas e conservação</h3><p>Consuma em 2–3 dias. O total usa 30 minutos de drenagem. Limão extra só se necessário, excluído da estimativa nutricional. O soro ácido não substitui leite ou creme para iogurte ou manteiga. Sem teste de cozinha próprio. Contém leite. Use utensílios limpos e higienizados e conserve a 4 °C ou menos. Não é uma conserva para guardar à temperatura ambiente.</p><ul><li><a href=\"https://ucanr.edu/sites/camasterfoodpreservers/files/404614.pdf\">UC Master Food Preservers — whole milk ricotta, page 21</a></li><li><a href=\"https://cheesemaking.com/pages/ricotta-cheese-making-recipe-instructions\">New England Cheesemaking — ricotta</a></li></ul>", "ingredients": [{"name": "leite integral pasteurizado, preferencialmente não UHT", "amount": "2000", "unit": "ml"}, {"name": "suco de limão espremido na hora e coado", "amount": "60", "unit": "ml"}, {"name": "sal fino", "amount": "2", "unit": "g"}], "steps": [{"title": "Aqueça o leite", "content": "Higienize panela, peneira e pano. Aqueça mexendo suavemente até 88–90 °C, sem fervura forte. Retire do fogo.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-01.webp", "image_alt": "Aqueça o leite — Ricota caseira de leite, macia e sem prensar"}, {"title": "Forme os flocos", "content": "Adicione limão e sal e mexa só 2–3 voltas. Deixe imóvel 10 minutos até separar flocos brancos e soro amarelado. Se continuar leitoso, acrescente até 15 ml de limão e espere 5 minutos; a acidez varia.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-02.webp", "image_alt": "Forme os flocos — Ricota caseira de leite, macia e sem prensar"}, {"title": "Escorra sem prensar", "content": "Recolha com escumadeira para pano fino sobre peneira e tigela. Escorra 10–15 minutos para manter úmido. Não esprema; para firmar, continue até 30 minutos dentro da geladeira.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-03.webp", "image_alt": "Escorra sem prensar — Ricota caseira de leite, macia e sem prensar"}, {"title": "Resfrie e guarde", "content": "Passe para recipiente limpo e tampado e refrigere por pelo menos 2 horas. Sirva esfarelada ou em recheios. Não bata se quiser manter os flocos.", "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/paso-04.webp", "image_alt": "Resfrie e guarde — Ricota caseira de leite, macia e sem prensar"}], "category": "Acompanhamentos", "course": "Acompanhamentos", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 190, "servings": 7, "image_url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada.webp", "alt": "Ricota caseira de leite, macia e sem prensar"}], "video_urls": [], "keywords": ["Ricota caseira de leite, macia e sem prensar"], "nutrition": {"calories": 87, "protein_g": 5.6, "carbs_g": 1.5, "fat_g": 6.5, "serving_size": "1 de 7 porções, cerca de 50 g", "estimated": true, "note": "Estimativa por porção; rendimento, umidade e marcas alteram os valores.", "source": "USDA FoodData Central generic whole-milk ricotta proxy", "method": "Finished ricotta reference per 100 g:174 kcal,11.2 g protein,3 g carbohydrate,13 g fat; multiply by 0.5 per 50 g portion. Assumed yield350 g from2 L milk; actual300–450 g. Whey excluded; not a sum of all milk nutrients."}, "seo": {"title": "Ricota caseira de leite, macia e sem prensar", "description": "Faça ricota caseira de leite e limão, macia para recheios ou café da manhã. Fotos da coagulação e drenagem, rendimento aproximado e conservação na geladeira.", "author": "Néstor Bastidas", "image_alt": "Ricota caseira de leite, macia e sem prensar", "image_variants": ["https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-1x1.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-4x3.webp", "https://manualdecocina.com/recetas/requeson-casero-de-leche/portada-16x9.webp"], "faq": [{"q": "Posso usar só soro?", "a": "Não nessas quantidades: proteínas e acidez diferem. Esta receita foi formulada para leite."}, {"q": "Por que fica seca?", "a": "Drenagem longa, pressão ou fervura forte secam os flocos. Escorra menos, sem peso."}], "additional_time_minutes": 160}, "published": false, "editorial_status": "ready"}]$payload$::jsonb;
foods jsonb := $foods$[]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "leche", "alias": "leche entera pasteurizada, preferiblemente no UHT"}, {"slug": "limon", "alias": "zumo de limón recién exprimido y colado"}, {"slug": "sal", "alias": "sal fina"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),'Ingrediente para elaboraciones lácteas domésticas.','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>3 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
FOR v IN SELECT * FROM public.recipes WHERE recipe_group_id=group_id LOOP
 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 UPDATE public.recipes SET editorial_status='published' WHERE id=v.id;
END LOOP;
END $dairy$;
SELECT language,public_path,published FROM public.recipes WHERE recipe_group_id=(SELECT recipe_group_id FROM public.recipes WHERE language='es' AND slug='requeson-casero-de-leche') ORDER BY language;
